            readback_data_var[0] = field_storage.MLKEM_SHARED_KEY.IRQ_STATUS.key_valid.value;
            readback_data_var[31:1] = 31'h0;
        end
        if(rd_mux_addr == 11'h428) begin
            readback_data_var[0] = field_storage.MLKEM_SHARED_KEY.IRQ_ENABLE.key_valid_en.value;
            readback_data_var[31:1] = 31'h0;
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = decoded_err;
    end

    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
